(3533385, 494683, 3746, '<td valign="top">Arrgh, more light godammit!! Could of been a great image. 6<br/> <br/> <br/>2nd time around in voting and bumping to a 7</td>', 'Arrgh, more light godammit!! Could of been a great image. 6  2nd time around in voting and bumping to a 7', '2007-04-09 16:55:46.000000', NULL, 1),
