(3539892, 494732, 52500, '<td valign="top">Interesting!  It seems to me that very few photos work well as a negative.  This is one of them.  I like the way it makes the chain look as though it is lit from the inside.  The blue tones are nice as well.</td>', 'Interesting!  It seems to me that very few photos work well as a negative.  This is one of them.  I like the way it makes the chain look as though it is lit from the inside.  The blue tones are nice as well.', '2007-04-11 15:06:47.000000', NULL, 1),
(3540008, 494498, 76301, '<td valign="top">I really like the way you thought out sidethe box and used no chains yet we all get the point</td>', 'I really like the way you thought out sidethe box and used no chains yet we all get the point', '2007-04-11 15:59:31.000000', NULL, 1),
(3540101, 494691, 76081, '<td valign="top">would be a much better photo if your model''s face expressed more... otherwise great</td>', 'would be a much better photo if your model''s face expressed more... otherwise great', '2007-04-11 16:39:40.000000', NULL, 1),
