(3550330, 494211, 53316, '<td valign="top">Happy Easter.  This is one of my favorites because of the way it meets the challenge as well  as the artisticness of it.  It is simple but very emotionally effective.  10.</td>', 'Happy Easter.  This is one of my favorites because of the way it meets the challenge as well  as the artisticness of it.  It is simple but very emotionally effective.  10.', '2007-04-15 23:55:07.000000', NULL, 1),
(3550332, 494593, 53316, '<td valign="top">One of my top five images.  Hauntingly beautiful... nice composition and color... a neat blend of abstract and concrete. 10.</td>', 'One of my top five images.  Hauntingly beautiful... nice composition and color... a neat blend of abstract and concrete. 10.', '2007-04-15 23:55:16.000000', NULL, 1),
(3550333, 494712, 53316, '<td valign="top">One of my top five favorites! Perfect balance between stillness and motion.. lovely tones and composition... very nice. 10.<br/> <br/>edit: Well, I guess this image made an impact on me.  I had a dream about it last night!!</td>', 'One of my top five favorites! Perfect balance between stillness and motion.. lovely tones and composition... very nice. 10. edit: Well, I guess this image made an impact on me.  I had a dream about it last night!!', '2007-04-15 23:55:23.000000', NULL, 1);
